 public static class MouseButtonsUiFacts {
  public static readonly string[] Sources={"leftButton","rightButton","middleButton","sideKeyLeftBackward","sideKeyLeftForward","dpi1","scrollUp","scrollDown"};
  public static readonly string[] MouseFunctions={"MouseClickLeft","MouseClickRight","MouseClickMiddle","MouseScrollUp","MouseScrollDown","MouseDPISwitch","MouseLeftBackward","MouseLeftForward","MouseTargetFocus","MouseDoubleClick"};
  static object Field(IDictionary<string,object> state,string key){object value;return state!=null&&state.TryGetValue(key,out value)?value:null;}
  static bool Flag(IDictionary<string,object> state,string key,bool value){object raw=Field(state,key);return raw is bool&&(bool)raw==value;}
  static int? Number(object raw,int min,int max){return raw is int&&(int)raw>=min&&(int)raw<=max?(int?)raw:null;}
  public static string[] Options(IDictionary<string,object> state,string key){var settings=Field(state,"settingOptions") as IDictionary<string,object>;var items=Field(settings,key) as IEnumerable;if(items==null||items is string)return new string[0];return items.Cast<object>().Where(item=>item is string&&!String.IsNullOrWhiteSpace((string)item)).Cast<string>().Distinct(StringComparer.Ordinal).ToArray();}
  static bool Capability(IDictionary<string,object> state,string key,string value){var items=Field(state,key) as IEnumerable;return items!=null&&!(items is string)&&items.Cast<object>().Any(item=>item is string&&(string)item==value);}
  public static int? TargetCode(string name){
   if(name==null)return null;if(name.Length==4&&name.StartsWith("Key",StringComparison.Ordinal)&&name[3]>='A'&&name[3]<='Z')return 4+name[3]-'A';
   if(name.Length==6&&name.StartsWith("Digit",StringComparison.Ordinal)&&name[5]>='0'&&name[5]<='9')return name[5]=='0'?39:29+name[5]-'0';
   int f;if(name.StartsWith("F",StringComparison.Ordinal)&&Int32.TryParse(name.Substring(1),NumberStyles.None,CultureInfo.InvariantCulture,out f)&&f>=1&&f<=12&&name=="F"+f)return 57+f;
   switch(name){case "Enter":return 40;case "Escape":return 41;case "Backspace":return 42;case "Tab":return 43;case "Space":return 44;case "ArrowRight":return 79;case "ArrowLeft":return 80;case "ArrowDown":return 81;case "ArrowUp":return 82;case "LeftCtrl":return 224;case "LeftShift":return 225;case "LeftAlt":return 226;case "LeftWin":return 227;case "RightCtrl":return 228;case "RightShift":return 229;case "RightAlt":return 230;case "RightWin":return 231;case "MultimediaPlayPause":return 240;case "MultimediaStop":return 241;case "MultimediaPrevTrack":return 242;case "MultimediaNextTrack":return 243;case "MultimediaMute":return 244;case "MultimediaVolumeDown":return 245;case "MultimediaVolumeUp":return 246;case "ShiftMode":return 253;case "MouseProfile":return 480;case "MouseDoubleClick":return 483;case "MouseLeftBackward":return 484;case "MouseLeftForward":return 485;case "MouseDPISwitch":return 486;case "MouseTargetFocus":return 487;case "MouseScrollUp":return 488;case "MouseScrollDown":return 489;case "MouseClickLeft":return 496;case "MouseClickRight":return 497;case "MouseClickMiddle":return 498;case "MouseDpiUp":return 499;case "MouseDpiDown":return 500;case "KeyDisabled":return 511;default:return null;}
  }
  public static string Caption(string name){switch(name){case "leftButton":case "MouseClickLeft":return "左键";case "rightButton":case "MouseClickRight":return "右键";case "middleButton":case "MouseClickMiddle":return "滚轮点击";case "sideKeyLeftForward":case "MouseLeftForward":return "前进";case "sideKeyLeftBackward":case "MouseLeftBackward":return "后退";case "scrollUp":case "MouseScrollUp":return "向上滚动";case "scrollDown":case "MouseScrollDown":return "向下滚动";case "dpi1":case "MouseDPISwitch":return "DPI 切换";case "MouseTargetFocus":return "狙击锁定";case "MouseDoubleClick":return "双击";default:if(name!=null&&name.Length==4&&name.StartsWith("Key",StringComparison.Ordinal)&&name[3]>='A'&&name[3]<='Z')return name.Substring(3);return "—";}}
  public static string Category(string target){return target!=null&&target.StartsWith("Mouse",StringComparison.Ordinal)||target=="KeyDisabled"?"mouse":target=="ShiftMode"?"speedshift":target!=null&&target.StartsWith("Multimedia",StringComparison.Ordinal)?"media":TargetCode(target).HasValue?"keyboard":"unknown";}
  public static MouseButtonObservation Read(IDictionary<string,object> state,string source,bool shift){
   var result=new MouseButtonObservation{Source=source,Shift=shift,DeviceId=Field(state,"deviceId") as string,CapturedAt=Field(state,"capturedAt") as string};var snapshot=Field(state,"snapshot") as IDictionary<string,object>;int? pid=Number(Field(state,"pid"),0,65535);
   result.IdentityConfirmed=pid.HasValue&&(pid==7546||pid==7548)&&KeyboardLightingUiFacts.Identity(result.DeviceId,pid.Value)&&Field(state,"kind") as string=="mouse"&&Number(Field(snapshot,"modelPid"),0,65535)==pid&&Flag(state,"connected",true)&&Flag(state,"online",true)&&Flag(state,"readbackConfirmed",true);
   result.SourceAvailable=result.IdentityConfirmed&&Sources.Contains(source,StringComparer.Ordinal)&&Options(state,"buttonSources").Contains(source,StringComparer.Ordinal);
   string field=shift?"shiftButtonBindings":"buttonBindings";var bindings=Field(snapshot,field) as IDictionary<string,object>;var binding=Field(bindings,source??"") as IDictionary<string,object>;
   if(!result.SourceAvailable||!Capability(state,"readCapabilities",field)||binding==null)return result;
   result.Target=Field(binding,"target") as string;result.TargetCode=Number(Field(binding,"targetCode"),0,65535);
   result.BindingKnown=result.TargetCode.HasValue&&TargetCode(result.Target)==result.TargetCode&&Options(state,"buttonTargets").Contains(result.Target,StringComparer.Ordinal);
   return result;
  }
  public static bool StampValid(string value){return !String.IsNullOrWhiteSpace(value)&&value.Length<=128;}
  public static bool CanChooseMouse(IDictionary<string,object> state,MouseButtonObservation observed){return observed!=null&&observed.BindingKnown&&StampValid(observed.CapturedAt)&&Capability(state,"setCapabilities","buttonBinding")&&Options(state,"buttonTargets").Any(value=>MouseFunctions.Contains(value,StringComparer.Ordinal));}
  public static bool Matches(IDictionary<string,object> state,MouseButtonsDraft draft){if(draft==null)return false;var observed=Read(state,draft.SelectedButton,draft.Shift);return observed.BindingKnown&&StampValid(observed.CapturedAt)&&observed.DeviceId==draft.DeviceId&&observed.CapturedAt==draft.CapturedAt&&observed.Target==draft.BaselineTarget&&observed.TargetCode==draft.BaselineCode;}
  public static Dictionary<string,object> Command(IDictionary<string,object> state,MouseButtonsDraft draft){if(draft==null||!draft.Dirty||draft.Type!="mouse"||!Matches(state,draft)||!CanChooseMouse(state,Read(state,draft.SelectedButton,draft.Shift))||!MouseFunctions.Contains(draft.Target,StringComparer.Ordinal)||!Options(state,"buttonTargets").Contains(draft.Target,StringComparer.Ordinal)||draft.Target==draft.BaselineTarget)return null;return new Dictionary<string,object>{{"button",draft.SelectedButton},{"target",draft.Target},{"shift",draft.Shift}};}
 }
